package mz.co.aprendaacodar.course.controller;
import jakarta.validation.Valid;import mz.co.aprendaacodar.course.dto.LearningDtos.*;import mz.co.aprendaacodar.course.service.LearningContentService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class LearningContentController {private final LearningContentService service;public LearningContentController(LearningContentService s){service=s;}
 @PostMapping("/courses/{courseId}/modules") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public ModuleResponse addModule(Authentication a,@PathVariable UUID courseId,@Valid @RequestBody ModuleRequest r){return service.addModule((UUID)a.getPrincipal(),courseId,r);}
 @GetMapping("/courses/{courseId}/modules") public List<ModuleResponse> modules(@PathVariable UUID courseId){return service.modules(courseId);}
 @PutMapping("/modules/{moduleId}") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public ModuleResponse updateModule(Authentication a,@PathVariable UUID moduleId,@Valid @RequestBody ModuleRequest r){return service.updateModule((UUID)a.getPrincipal(),moduleId,r);}
 @DeleteMapping("/modules/{moduleId}") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public void deleteModule(Authentication a,@PathVariable UUID moduleId){service.deleteModule((UUID)a.getPrincipal(),moduleId);}
 @PatchMapping("/modules/{moduleId}/reorder") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public void reorderModule(Authentication a,@PathVariable UUID moduleId,@Valid @RequestBody PositionRequest r){service.reorderModule((UUID)a.getPrincipal(),moduleId,r.position());}
 @PostMapping("/courses/{courseId}/lessons") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public LessonResponse addLesson(Authentication a,@PathVariable UUID courseId,@Valid @RequestBody LessonRequest r){return service.addLesson((UUID)a.getPrincipal(),courseId,r);}
 @GetMapping("/courses/{courseId}/lessons") public List<LessonSummary> lessons(Authentication a,@PathVariable UUID courseId){return service.courseLessons((UUID)a.getPrincipal(),courseId);}
 @GetMapping("/lessons/{lessonId}") public LessonResponse lesson(Authentication a,@PathVariable UUID lessonId){return service.getLesson((UUID)a.getPrincipal(),lessonId);}
 @PutMapping("/lessons/{lessonId}") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public LessonResponse update(Authentication a,@PathVariable UUID lessonId,@Valid @RequestBody LessonRequest r){return service.updateLesson((UUID)a.getPrincipal(),lessonId,r);}
 @DeleteMapping("/lessons/{lessonId}") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public void delete(Authentication a,@PathVariable UUID lessonId){service.deleteLesson((UUID)a.getPrincipal(),lessonId);}
 @PatchMapping("/lessons/{lessonId}/reorder") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public void reorderLesson(Authentication a,@PathVariable UUID lessonId,@Valid @RequestBody PositionRequest r){service.reorderLesson((UUID)a.getPrincipal(),lessonId,r.position());}
 @PostMapping(value="/lessons/{lessonId}/resources",consumes="multipart/form-data") @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('TEACHER','ADMIN')") public ResourceResponse addResource(Authentication a,@PathVariable UUID lessonId,@RequestParam String name,@RequestParam(required=false) String description,@RequestPart("file") org.springframework.web.multipart.MultipartFile file){return service.addResource((UUID)a.getPrincipal(),lessonId,name,description,file);}
 @GetMapping("/resources/{resourceId}/download") public DownloadResponse download(Authentication a,@PathVariable UUID resourceId){return service.download((UUID)a.getPrincipal(),resourceId);}
}
